// Izhikevich (2007) medium spiny neuron, scaled form; dt in ms, I in pA
const msn = { C: 50, k: 1, vr: -80, vt: -25, a: 0.01, b: -20,
              c: -55, d: 150, vpeak: 40 };
function msnStep(n, I, dt) {
  const p = msn;
  n.v += dt * (p.k * (n.v - p.vr) * (n.v - p.vt) - n.u + I) / p.C;
  n.u += dt * p.a * (p.b * (n.v - p.vr) - n.u);
  if (n.v >= p.vpeak) { n.v = p.c; n.u += p.d; return true; }
  return false;
}
// start at n = { v: -80, u: 0 }; the deep rest and high threshold mean
// about 400 pA are needed before the first spike, which then comes
// only after a delay of a few hundred ms.
